<script setup>
import { $api } from '@/utils/api'
const meta=ref({members:[]}), facilities=ref([]), bookings=ref([]), result=ref(null), hold=ref(null), error=ref(''), busy=ref(false)
const form=reactive({member_id:null,facility_id:null,date:new Date(Date.now()+86400000).toISOString().slice(0,10),start_time:'10:00',duration:60,guest_count:0})
const money=(v,c='ZAR')=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:c}).format((v||0)/100)
const payload=()=>{const start=new Date(`${form.date}T${form.start_time}:00+02:00`);return{member_id:form.member_id,facility_id:form.facility_id,starts_at:start.toISOString(),ends_at:new Date(start.getTime()+form.duration*60000).toISOString(),guest_count:form.guest_count}}
async function load(){[meta.value,facilities.value]=await Promise.all([$api('/booking/facilities/meta'),$api('/booking/facilities')]);bookings.value=(await $api('/bookings')).data}
async function simulate(){busy.value=true;error.value='';try{result.value=await $api('/booking/simulate',{method:'POST',body:payload()})}catch(e){error.value=e?.data?.message||'Slot could not be evaluated.'}finally{busy.value=false}}
async function createHold(){busy.value=true;error.value='';try{hold.value=await $api('/booking/holds',{method:'POST',body:{...payload(),idempotency_key:crypto.randomUUID()}})}catch(e){error.value=e?.data?.message||'Hold could not be created.'}finally{busy.value=false}}
async function confirm(){busy.value=true;error.value='';try{await $api(`/booking/holds/${hold.value.id}/confirm`,{method:'POST',body:{confirmation_key:crypto.randomUUID(),participants:[]}});hold.value=null;result.value=null;await load()}catch(e){error.value=e?.data?.message||'Booking could not be confirmed.'}finally{busy.value=false}}
async function cancel(item){const reason=window.prompt('Cancellation reason');if(!reason)return;await $api(`/bookings/${item.id}/cancel`,{method:'POST',body:{reason}});await load()}
onMounted(load)
</script>
<template><div><div class="mb-6"><h3 class="text-h3">Court bookings</h3><p class="text-medium-emphasis">Day and mobile-list booking with server-calculated rules, allowance and price.</p></div><VAlert v-if="error" type="error" class="mb-4">{{error}}</VAlert>
<VRow><VCol cols="12" lg="5"><VCard><VCardTitle>Find a court</VCardTitle><VCardText><VSelect v-model="form.member_id" :items="meta.members" item-title="display_name" item-value="id" label="Member"/><VSelect v-model="form.facility_id" :items="facilities" item-title="name" item-value="id" label="Facility"/><VRow><VCol cols="7"><VTextField v-model="form.date" type="date" label="Date"/></VCol><VCol cols="5"><VTextField v-model="form.start_time" type="time" label="Start"/></VCol></VRow><VSelect v-model="form.duration" :items="[30,60,90,120]" label="Duration (minutes)"/><VTextField v-model.number="form.guest_count" type="number" min="0" label="Guests"/><div class="d-flex gap-2"><VBtn :loading="busy" :disabled="!form.member_id||!form.facility_id" @click="simulate">Check rules and price</VBtn><VBtn v-if="result?.eligible" variant="tonal" @click="createHold">Hold slot</VBtn></div></VCardText></VCard>
<VCard v-if="result" class="mt-4"><VCardTitle>{{result.eligible?'Available':'Not available'}}</VCardTitle><VCardText><p><strong>Profile:</strong> {{result.profile.profile.replaceAll('_',' ')}}</p><p><strong>Price:</strong> {{money(result.price.total_amount,result.price.currency)}}</p><p><strong>Allowance:</strong> {{result.allowance.minutes||0}} minutes / {{money(result.allowance.value_cents)}}</p><p><strong>Cancel by:</strong> {{new Date(result.cancellation.cancellation_deadline).toLocaleString()}}</p><VList density="compact"><VListItem v-for="check in result.checks" :key="check.code" :prepend-icon="check.passed?'tabler-circle-check':'tabler-alert-circle'" :title="check.code.replaceAll('_',' ')" :subtitle="check.passed?'Passed':check.member_message"/></VList></VCardText></VCard>
<VAlert v-if="hold" type="warning" class="mt-4"><div>Held until {{new Date(hold.expires_at).toLocaleTimeString()}}</div><VBtn class="mt-2" size="small" @click="confirm">Confirm booking</VBtn></VAlert></VCol>
<VCol cols="12" lg="7"><VCard><VCardTitle>My and authorized bookings</VCardTitle><VTable><thead><tr><th>Reference</th><th>Court</th><th>Start</th><th>Status</th><th>Payment</th><th/></tr></thead><tbody><tr v-for="item in bookings" :key="item.id"><td>{{item.booking_reference}}</td><td>{{item.facility.name}}</td><td>{{new Date(item.starts_at).toLocaleString()}}</td><td>{{item.status.replaceAll('_',' ')}}</td><td>{{item.payment_status.replaceAll('_',' ')}}</td><td><VBtn v-if="!['cancelled','completed'].includes(item.status)" size="small" variant="text" @click="cancel(item)">Cancel</VBtn></td></tr></tbody></VTable></VCard></VCol></VRow></div></template>
